import os
import time
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _to_millis(dt: datetime) -> int:
    return int(dt.timestamp() * 1000)


def _normalize_events(events: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized = []
    for event in events:
        normalized.append(
            {
                "timestamp": event.get("timestamp"),
                "message": event.get("message"),
                "ingestionTime": event.get("ingestionTime"),
                "logStreamName": event.get("logStreamName"),
                "logGroupName": event.get("logGroupName"),
                "eventId": event.get("eventId"),
            }
        )
    return normalized


def query_recent_logs(
    log_group_name: str,
    field_filters: Optional[Dict[str, Any]] = None,
    minutes_back: int = 60,
    limit: int = 100,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Retrieve recent CloudWatch Logs matching field values and a time range.

    Args:
        log_group_name: CloudWatch Logs log group name.
        field_filters: Mapping of field names to exact-match values.
            Examples: {"service": "api", "level": "ERROR"}.
        minutes_back: Look back this many minutes from now (UTC).
        limit: Maximum number of results to return.
        region_name: AWS region. Falls back to AWS_REGION/AWS_DEFAULT_REGION.

    Returns:
        A list of matching log events.
    """
    if minutes_back < 0:
        raise ValueError("minutes_back must be non-negative")
    if limit <= 0:
        return []

    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    client = boto3.client("logs", region_name=region)

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(minutes=minutes_back)

    filters = field_filters or {}
    filter_pattern = None
    if filters:
        parts = []
        for key, value in filters.items():
            if isinstance(value, str):
                escaped = value.replace('"', '\\"')
                parts.append(f'$.{key} = "{escaped}"')
            elif isinstance(value, bool):
                parts.append(f"$.{key} = {str(value).lower()}")
            else:
                parts.append(f"$.{key} = {value}")
        filter_pattern = " && ".join(parts)

    try:
        paginator = client.get_paginator("filter_log_events")
        pagination_kwargs = {
            "logGroupName": log_group_name,
            "startTime": _to_millis(start_time),
            "endTime": _to_millis(end_time),
            "PaginationConfig": {"PageSize": min(max(limit, 1), 1000)},
        }
        if filter_pattern:
            pagination_kwargs["filterPattern"] = filter_pattern

        results: List[Dict[str, Any]] = []
        for page in paginator.paginate(**pagination_kwargs):
            results.extend(page.get("events", []))
            if len(results) >= limit:
                break

        results = results[:limit]
        return _normalize_events(results)

    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"Failed to query CloudWatch Logs: {exc}") from exc


def ingest_log_event(
    log_group_name: str,
    log_stream_name: str,
    message: str,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Ingest a single log event into Amazon CloudWatch Logs.

    This is included to support managed log ingestion as part of the same provider.
    """
    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    client = boto3.client("logs", region_name=region)

    try:
        try:
            client.create_log_group(logGroupName=log_group_name)
        except ClientError as exc:
            if exc.response.get("Error", {}).get("Code") not in {"ResourceAlreadyExistsException"}:
                raise

        try:
            client.create_log_stream(logGroupName=log_group_name, logStreamName=log_stream_name)
        except ClientError as exc:
            if exc.response.get("Error", {}).get("Code") not in {"ResourceAlreadyExistsException"}:
                raise

        resp = client.describe_log_streams(
            logGroupName=log_group_name,
            logStreamNamePrefix=log_stream_name,
            orderBy="LogStreamName",
            descending=False,
            limit=1,
        )

        upload_sequence_token = None
        streams = resp.get("logStreams", [])
        if streams:
            upload_sequence_token = streams[0].get("uploadSequenceToken")

        put_kwargs = {
            "logGroupName": log_group_name,
            "logStreamName": log_stream_name,
            "logEvents": [{"timestamp": int(time.time() * 1000), "message": message}],
        }
        if upload_sequence_token:
            put_kwargs["sequenceToken"] = upload_sequence_token

        return client.put_log_events(**put_kwargs)

    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"Failed to ingest CloudWatch Logs event: {exc}") from exc
